import random, codecs
from decoder import Decoder

def ref_parse(data, max_size):
    """Reference: returns list of strings, raises ValueError on malformed."""
    out=[]; i=0; n=len(data)
    while i<n:
        j=i
        while j<n and data[j:j+1].isdigit(): j+=1
        if j==i: raise ValueError("empty/invalid length")
        head=data[i:j]
        if head[0:1]==b'0' and len(head)>1: raise ValueError("leading zero")
        val=int(head)
        if val>max_size: raise ValueError("too big")
        if j>=n or data[j:j+1]!=b':': raise ValueError("no colon")
        j+=1
        if j+val>n: raise ValueError("short payload")
        payload=data[j:j+val]; j+=val
        if j>=n or data[j:j+1]!=b',': raise ValueError("no comma")
        j+=1
        out.append(payload.decode('utf-8'))
        i=j
    return out

random.seed(1234)
