import random
from coverage import coverage

def brute(intervals, start, end):
    covered_ints = set()
    for lo, hi in intervals:
        for x in range(lo, hi):
            if start <= x < end:
                covered_ints.add(x)
    merged = []
    gaps = []
    if start < end:
        run = None
        for x in range(start, end):
            if x in covered_ints:
                if run is None:
                    run = [x, x + 1]
                else:
                    run[1] = x + 1
            else:
                if run is not None:
                    merged.append(run); run = None
        if run is not None:
            merged.append(run)
        cur = start
        for a, b in merged:
            if a > cur:
                gaps.append([cur, a])
            cur = max(cur, b)
        if cur < end:
            gaps.append([cur, end])
    return {"merged": merged, "gaps": gaps, "covered": len(covered_ints)}

random.seed(0)
for _ in range(20000):
    start = random.randint(-6, 6)
    end = random.randint(start, 6)
    n = random.randint(0, 5)
    intervals = []
    for _ in range(n):
        lo = random.randint(-8, 8)
        hi = random.randint(lo, 8)
        intervals.append([lo, hi] if random.random() < 0.5 else (lo, hi))
    got = coverage(intervals, start, end)
    exp = brute([list(i) for i in intervals], start, end)
    if got != exp:
        print("MISMATCH", intervals, start, end, got, exp)
        break
else:
    print("all random cases match brute force")
